-- Canonical expression deparse must not depend on connection timezone/search_path.
set search_path=pg_catalog;
set timezone='UTC';
-- Read-only catalog inventory. No relation rows, function bodies, passwords or cron commands leave this query.
select jsonb_build_object(
 'identity',jsonb_build_object('database',current_database(),'databaseOid',(select oid::text from pg_database where datname=current_database()),'sessionUser',session_user,'serverAddress',host(inet_server_addr()),'serverPort',inet_server_port(),'version',current_setting('server_version_num')::int,'inRecovery',pg_is_in_recovery()),
 'settings',jsonb_build_object('walLevel',current_setting('wal_level'),'maxReplicationSlots',current_setting('max_replication_slots')::int,'maxWalSenders',current_setting('max_wal_senders')::int,'preparedTransactions',(select count(*) from pg_prepared_xacts where database=current_database()),'logicalWorkers',current_setting('max_logical_replication_workers')::int),
 'schemas',(select coalesce(jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',(select coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]') from aclexplode(coalesce(nspacl,acldefault('n',nspowner))) a)) order by nspname),'[]') from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema'),
 'extensions',(select coalesce(jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) order by e.extname),'[]') from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
 'largeObjectCount',(select count(*) from pg_largeobject_metadata),
 'extensionDependencies',(select coalesce(jsonb_agg(distinct e.extname),'[]') from pg_depend d join pg_depend ed on ed.classid=d.refclassid and ed.objid=d.refobjid and ed.deptype='e' and ed.refclassid='pg_extension'::regclass join pg_extension e on e.oid=ed.refobjid where (d.classid='pg_class'::regclass and d.objid in(select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(:'schemas'::text[]))) or (d.classid='pg_attrdef'::regclass and d.objid in(select ad.oid from pg_attrdef ad join pg_class c on c.oid=ad.adrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(:'schemas'::text[]))) or (d.classid='pg_proc'::regclass and d.objid in(select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=any(:'schemas'::text[]))) or (d.classid='pg_rewrite'::regclass and d.objid in(select rw.oid from pg_rewrite rw join pg_class c on c.oid=rw.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(:'schemas'::text[])))),
 'availableExtensions',(select coalesce(jsonb_agg(name order by name),'[]') from pg_available_extensions),
 'roles',(select coalesce(jsonb_agg(jsonb_build_object('name',rolname,'login',rolcanlogin,'superuser',rolsuper,'bypassRls',rolbypassrls,'replication',rolreplication,'canReadSubscriptionConninfo',has_column_privilege(oid,'pg_catalog.pg_subscription','subconninfo','SELECT'),'setReplicationRole',has_parameter_privilege(oid,'session_replication_role','SET'),'canAssumeMigration',pg_has_role(oid,:'migration_role'::regrole,'MEMBER'),'canCreateApplicationObjects',exists(select from pg_namespace cn where cn.nspname=any(:'schemas'::text[]) and has_schema_privilege(r.oid,cn.oid,'CREATE')),'ownsApplicationTables',exists(select from pg_class ac join pg_namespace an on an.oid=ac.relnamespace where an.nspname=any(:'schemas'::text[]) and ac.relkind in('r','p') and pg_has_role(r.oid,ac.relowner,'MEMBER')),'membersOf',(select coalesce(jsonb_agg(pg_get_userbyid(roleid) order by roleid),'[]') from pg_auth_members where member=r.oid)) order by rolname),'[]') from pg_roles r),
 'tables',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'kind',c.relkind,'persistence',c.relpersistence,'partition',c.relispartition,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'replicaIdentity',c.relreplident,'acl',(select coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]') from aclexplode(coalesce(c.relacl,acldefault((case when c.relkind='S' then 's' else 'r' end)::"char",c.relowner))) a),
   'primaryKey',(select coalesce(jsonb_agg(a.attname order by k.ordinality),'[]') from pg_index i cross join lateral unnest(i.indkey) with ordinality k(attnum,ordinality) join pg_attribute a on a.attrelid=i.indrelid and a.attnum=k.attnum where i.indrelid=c.oid and i.indisprimary),
   'columns',(select coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'defaultHash',md5(pg_get_expr(d.adbin,d.adrelid)),'providers',(select coalesce(jsonb_agg(s),'[]') from unnest(array['auth','storage','net','vault','cron','realtime']) s where coalesce(pg_get_expr(d.adbin,d.adrelid),'') ~* ('\m"?'||s||'"?\s*\.\s*'||case when s='vault' then '"?(secrets|decrypted_secrets|create_secret|update_secret)\M' else '' end))) order by a.attnum),'[]') from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
   'indexes',(select coalesce(jsonb_agg(jsonb_build_object('name',ic.relname,'definitionHash',md5(pg_get_indexdef(i.indexrelid)),'valid',i.indisvalid) order by ic.relname),'[]') from pg_index i join pg_class ic on ic.oid=i.indexrelid where i.indrelid=c.oid),
   'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definitionHash',md5(pg_get_constraintdef(oid,true)),'referencedSchema',(select nspname from pg_class fc join pg_namespace fn on fn.oid=fc.relnamespace where fc.oid=confrelid),'validated',convalidated) order by conname),'[]') from pg_constraint where conrelid=c.oid),
   'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',polname,'command',polcmd,'roles',(select jsonb_agg(case when r=0 then 'public' else pg_get_userbyid(r) end order by case when r=0 then 'public' else pg_get_userbyid(r) end) from unnest(polroles) r),'usingHash',md5(pg_get_expr(polqual,polrelid)),'checkHash',md5(pg_get_expr(polwithcheck,polrelid)),'permissive',polpermissive) order by polname),'[]') from pg_policy where polrelid=c.oid),
   'triggers',(select coalesce(jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'definitionHash',md5(pg_get_triggerdef(oid))) order by tgname),'[]') from pg_trigger where tgrelid=c.oid and not tgisinternal and tgname<>'byus_migration_guard')
 ) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in('r','p') and n.nspname=any(:'schemas'::text[])),
 'types',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',ty.typname,'kind',ty.typtype,'owner',pg_get_userbyid(ty.typowner),'acl',(select coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]') from aclexplode(coalesce(ty.typacl,acldefault('T',ty.typowner))) a),'enumHash',(select md5(string_agg(enumlabel,E'\n' order by enumsortorder)) from pg_enum where enumtypid=ty.oid),'domainBase',format_type(ty.typbasetype,ty.typtypmod),'domainNotNull',ty.typnotnull,'domainDefaultHash',md5(ty.typdefault)) order by n.nspname,ty.typname),'[]') from pg_type ty join pg_namespace n on n.oid=ty.typnamespace where n.nspname=any(:'schemas'::text[]) and ty.typtype in('e','d')),
 'routines',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'securityDefiner',p.prosecdef,'settingsHash',md5(p.proconfig::text),'searchPath',(select v from unnest(p.proconfig) v where v like 'search_path=%' limit 1),'acl',(select coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]') from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a),'definitionHash',md5(pg_get_functiondef(p.oid)),
   'providers',(select coalesce(jsonb_agg(s),'[]') from unnest(array['auth','storage','net','vault','cron','realtime']) s where pg_get_functiondef(p.oid) ~* ('\m"?'||s||'"?\s*\.\s*'||case when s='vault' then '"?(secrets|decrypted_secrets|create_secret|update_secret)\M' else '' end))
 ) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=any(:'schemas'::text[]) and p.prokind in('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
 'views',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',(select coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]') from aclexplode(coalesce(c.relacl,acldefault((case when c.relkind='S' then 's' else 'r' end)::"char",c.relowner))) a),'definitionHash',md5(pg_get_viewdef(c.oid,true)),
  'providers',(select coalesce(jsonb_agg(s),'[]') from unnest(array['auth','storage','net','vault','cron','realtime']) s where pg_get_viewdef(c.oid,true) ~* ('\m"?'||s||'"?\s*\.\s*'||case when s='vault' then '"?(secrets|decrypted_secrets|create_secret|update_secret)\M' else '' end))
 ) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in('v','m') and n.nspname=any(:'schemas'::text[])),
 'sequences',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',(select coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'public' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]') from aclexplode(coalesce(c.relacl,acldefault((case when c.relkind='S' then 's' else 'r' end)::"char",c.relowner))) a),'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle,'binding',(select jsonb_build_object('schema',tn.nspname,'table',tc.relname,'column',a.attname) from pg_depend d join pg_class tc on tc.oid=d.refobjid join pg_namespace tn on tn.oid=tc.relnamespace join pg_attribute a on a.attrelid=tc.oid and a.attnum=d.refobjsubid where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype in('a','i') limit 1)) order by n.nspname,c.relname),'[]') from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(:'schemas'::text[])),
 'publications',(select coalesce(jsonb_agg(jsonb_build_object('name',pubname,'allTables',puballtables,'insert',pubinsert,'update',pubupdate,'delete',pubdelete,'truncate',pubtruncate) order by pubname),'[]') from pg_publication),
 'publicationTables',(select coalesce(jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename,'columns',attnames,'hasFilter',rowfilter is not null) order by pubname,schemaname,tablename),'[]') from pg_publication_tables),
 'slots',(select coalesce(jsonb_agg(jsonb_build_object('name',slot_name,'type',slot_type,'plugin',plugin,'database',database,'active',active,'confirmedFlushLsn',confirmed_flush_lsn::text,'walStatus',wal_status) order by slot_name),'[]') from pg_replication_slots),
 'subscriptions',(select coalesce(jsonb_agg(jsonb_build_object('name',subname,'enabled',subenabled,'slot',subslotname) order by subname),'[]') from pg_subscription where subdbid=(select oid from pg_database where datname=current_database())),
 'activity',(select coalesce(jsonb_agg(jsonb_build_object('role',usename,'state',state,'backendType',backend_type,'count',n)),'[]') from (select usename,state,backend_type,count(*) n from pg_stat_activity where datname=current_database() and pid<>pg_backend_pid() group by usename,state,backend_type) a)
);
